export function rotate90(m: number[][]): number[][] {
  const a = m.map((r) => [...r]);
  const n = a.length;
  for (let l = 0; l < Math.floor(n / 2); l++) {
    const f = l, e = n - 1 - l;
    for (let i = f; i < e; i++) {
      const o = i - f, t = a[f][i];
      a[f][i] = a[e - o][f];
      a[e - o][f] = a[e][e - o];
      a[e][e - o] = a[i][e];
      a[i][e] = t;
    }
  }
  return a;
}
